 "content": "from collections import deque


def transform(grid):
    """Tile each non-8 panel with the colored motif's bounding-box pattern."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 8 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            colored = [(y, x) for y, x in cells if grid[y][x] not in (0, 8)]
            if not colored:
                continue
            r0, r1 = min(y for y, x in colored), max(y for y, x in colored)
            c0, c1 = min(x for y, x in colored), max(x for y, x in colored)
            ph, pw = r1 - r0 + 1, c1 - c0 + 1
            pattern = [[grid[r0 + dy][c0 + dx] for dx in range(pw)] for dy in range(ph)]
            for y, x in cells:
                out[y][x] = pattern[(y - r0) % ph][(x - c0) % pw]
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
